def read_number(prompt):
    """Keep asking until the user types a valid number."""
    while True:
        raw = input(prompt)
        try:
            return float(raw)
        except ValueError:
            print(f"'{raw}' is not a number - try again.")

price = read_number("Price? ")
qty = read_number("How many? ")
print(f"Total: {price * qty}")

