import random

def roll_die(sides=6):
    """Roll one die with the given number of sides."""
    return random.randint(1, sides)

print("Three rolls of a 6-sided die:")
for i in range(3):
    print("  roll", i + 1, "=", roll_die())

print("A 20-sided die:", roll_die(20))
